#!/usr/bin/env ruby
require 'json';require 'open3';require 'fileutils';root=File.expand_path('..',__dir__);source=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/repair/RepairDryRun.java'));jdk=File.expand_path('../.toolchains/jdk-26.0.2.1.jdk/Contents/Home',root);env={'JAVA_HOME'=>jdk,'PATH'=>"#{jdk}/bin:#{ENV['PATH']}"};out,err,status=Open3.capture3(env,'./mvnw','-pl','server/GameCommon','-am','-Dtest=RepairDryRunTest','-Dsurefire.failIfNoSpecifiedTests=false','test','-q',chdir:root);checks={'hit_count'=>source.include?('matched'),'samples'=>source.include?('sampleLimit'),'estimated_change'=>source.include?('estimatedChanges'),'invariants'=>source.include?('invariantViolations'),'non_mutating'=>source.include?('mutationAttempted'),'tests_passed'=>status.success?};result={'task'=>'REPAIR02','passed'=>checks.values.all?,'checks'=>checks,'testStdout'=>out.strip,'testStderr'=>err.strip};path=File.join(root,'work/audit/repair-dry-run.json');FileUtils.mkdir_p(File.dirname(path));File.write(path,JSON.pretty_generate(result)+"\n");puts JSON.generate(result);exit(result['passed'] ? 0 : 1)
